import json
with open('transcript.jsonl') as f:
    for line in f:
        obj = json.loads(line)
        t = obj.get('type')
        if t == 'assistant':
            msg = obj.get('message', {})
            for c in msg.get('content', []):
                if c.get('type') == 'text':
                    print('--- TEXT ---')
                    print(c['text'][:2000])
                elif c.get('type') == 'tool_use':
                    print('--- TOOL_USE', c.get('name'), '---')
                    print(json.dumps(c.get('input'))[:500])
        elif t == 'user':
            msg = obj.get('message', {})
            content = msg.get('content')
            if isinstance(content, list):
                for c in content:
                    if c.get('type') == 'tool_result':
                        cont = c.get('content')
                        s = json.dumps(cont)[:600] if not isinstance(cont, str) else cont[:600]
                        print('--- TOOL_RESULT ---')
                        print(s)
"

